def sudoku_valid(board) -> bool:
    if not isinstance(board, list) or len(board) != 9:
        raise ValueError("Board must be a 9x9 list of lists")
    for row in board:
        if not isinstance(row, list) or len(row) != 9:
            raise ValueError("Board must be a 9x9 list of lists")
        for val in row:
            if not isinstance(val, int) or val < 0 or val > 9:
                raise ValueError("Board values must be integers between 0 and 9")

    def has_duplicates(cells):
        seen = set()
        for v in cells:
            if v == 0:
                continue
            if v in seen:
                return True
            seen.add(v)
        return False

    # Check rows
    for row in board:
        if has_duplicates(row):
            return False

    # Check columns
    for col in range(9):
        column = [board[row][col] for row in range(9)]
        if has_duplicates(column):
            return False

    # Check 3x3 boxes
    for box_row in range(0, 9, 3):
        for box_col in range(0, 9, 3):
            box = [
                board[r][c]
                for r in range(box_row, box_row + 3)
                for c in range(box_col, box_col + 3)
            ]
            if has_duplicates(box):
                return False

    return True
